// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: contract_address (the callee), an array of recipients and amounts
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        // admissible domain: contract_address must be non-zero and not equal to address(c)
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        // require non-empty arrays and equal length per contract requirements
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // The callee must contain code that will accept the low-level call with selector
        // We cannot rely on arbitrary fuzzed address (EOA). Deploy a simple passthrough callee
        // at the provided contract_address by ignoring the fuzzed address and instead deploying
        // a helper, then using its address as the callee. The requirement forbids hard-coding
        // deciding values but allows deploying a helper to embody adversarial behaviour.
        // Here we deploy a well-behaved helper that returns successfully for transferFrom.
        Callee helper = new Callee();
        address calleeAddr = address(helper);

        // Call c.transfer via try/catch to capture non-revert completion as a boolean
        bool ok;
        bool ret;
        try c.transfer(calleeAddr, tos, vs) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The universal property: for every admissible input where the call does not revert (ok==true),
        // the reference implementation returns true. The mutant returns false for some such inputs.
        // We assert the property observed from c: if transfer completed (ok), its return must be true.
        assertTrue(!ok || ret);
    }
}

// Minimal well-behaved callee: exposes transferFrom(address,address,uint256) selector and succeeds
contract Callee {
    // emulate ERC20-like transferFrom signature
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: a non-zero address for contract_address is enforced via deploying a helper.
    // We fuzz two amounts and a length to build arrays; we also fuzz an arbitrary address 'actor' to be the msg.sender.
    function testFuzz_property(address actor, uint96 a0, uint96 a1, uint8 len) public {
        // Keep inputs in wide admissible domain
        vm.assume(actor != address(0));
        // ensure len at least 1 and small to keep test cheap
        uint256 l = uint256(bound(len, 1, 2));

        // Deploy a helper callee that will ALWAYS revert on transferFrom calls to trigger the difference
        Reverter rev = new Reverter();

        // Build tos and vs arrays of length l
        address[] memory tos = new address[](l);
        uint[] memory vs = new uint[](l);
        for (uint i = 0; i < l; i++) {
            tos[i] = address(0xABCD); // arbitrary target - not used by callee
            vs[i] = (i == 0) ? uint(a0) : uint(a1);
        }

        // The contract's transfer will call into the provided contract_address using call(...transferFrom...)
        // Use the reverter so the reference implementation should revert (call returns false -> require(_s) fails)
        bool ok;
        // make the call as actor so msg.sender inside c is actor
        vm.prank(actor);
        try c.transfer(address(rev), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: for the correct C, when the callee always reverts, c.transfer MUST revert (ok == false) for all admissible inputs.
        // The mutant that skips the loop will return true (ok == true) for some inputs; asserting that ok == false distinguishes them.
        assertTrue(ok == false);
    }
}

contract Reverter {
    // Accept any calldata but always revert to simulate a failing external call inside the loop
    fallback() external payable {
        revert("revert from callee");
    }
}

